window.AUTH=window.AUTH||{};window.AUTH["98-1701"]={"d":"98-1701","id":"1999/98-1701","n":"United States v. Locke","src":["osg"],"briefs":[{"k":"petitioner","label":"Brief for the United States","date":"","url":"https://www.justice.gov/osg/media/226106/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/us-v-locke-and-intertanko-v-locke-merits","n":89}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep529/usrep529089/usrep529089.pdf","tr":false,"items":[{"t":"case","label":"California v. Zook","cite":"336 U.S. 725","y":1949,"id":"scdb/1948-070","sc":1,"op":1,"sum":"The state statute, as so applied, is not invalid under the Commerce Clause of the Federal Constitution.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"Chicago & N.W. Transp. Co. v. Kalo Brick & Tile Co.","cite":"450 U.S. 311","y":1981,"id":"1980/79-1336","sc":1,"sum":"The Interstate Commerce Act precludes a shipper from pressing a state-court action for damages against a regulated rail carrier when, as here, the ICC, in approving the carrier's application for abandonment, reaches the merits of the matters the shipper seeks to raise in state court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"City of New York v. FCC","cite":"486 U.S. 57","y":1988,"id":"1987/87-339","sc":1,"op":3,"sum":"The FCC did not exceed its statutory authority by forbidding local authorities to impose technical cable signal quality standards more stringent than those set forth in the Commission's regulations.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46"}},{"t":"case","label":"Cooley v. Board of Wardens","cite":"53 U.S. 299","y":1852,"id":"1850-1900/53us299","sc":1,"op":2,"sum":"A Pennsylvania law requiring ships to hire a local pilot violates the Commerce Clause of the US Constitution.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"English v. General Elec. Co.","cite":"496 U.S. 72","y":1990,"id":"1989/89-152","sc":1,"op":4,"sum":"English's state-law claim for intentional infliction of emotional distress is not pre-empted by federal law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Fidelity Fed. Sav. & Loan Ass’n v. de la Cuesta","cite":"458 U.S. 141","y":1982,"id":"1981/81-750","sc":1,"op":1,"sum":"The Board's due-on-sale regulation pre-empts conflicting state limitations on the due-on-sale practices of federal savings and loan associations, and thus bars application of the Wellenkamp rule to such associations.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32, 46"}},{"t":"case","label":"Foster v. Davenport","cite":"63 U.S. 244","y":1859,"id":"scdb/1859-008","sc":1,"sum":"The principle established in the preceding ease extends also to a steamboat employed as a lighter and towboat, sometimes towing vessels beyond the outer bar of the bay, and into the gulf to the'distance of several milesi","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Gibbons v. Ogden","cite":"22 U.S. 1","y":1824,"id":"1789-1850/22us1","sc":1,"op":1,"sum":"The Court decided that the federal government has exclusive power over interstate commerce.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Harmon v. Chicago","cite":"147 U.S. 396","y":1893,"id":"scdb/1892-088","sc":1,"sum":"—Decided January 23,1893.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Hillsborough County v. Automated Med. Lab. Inc.","cite":"471 U.S. 707","y":1985,"id":"1984/83-1925","sc":1,"sum":"Appellant county's ordinances and implementing regulations are not pre-empted by the federal regulations.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"Hines v. Davidowitz","cite":"312 U.S. 52","y":1941,"id":"scdb/1940-064","sc":1,"sum":"1. Applicable legislation enacted while the case was pending on appeal will be enforced by the appellate court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"sum":"The Court held that the Immigration and Nationality Act violated the separation of powers by allowing a one-house veto over executive decisions.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Kelly v. Washington ex rel. Foss Co.","cite":"302 U.S. 1","y":1937,"id":"scdb/1937-007","sc":1,"op":38,"sum":"On reargument, Mr. E. P. Donnelly for petitioners, and Mr. Glenn J. Eairbrook for respondents. Assistant Solicitor General Bell, with whom Solicitor General Reed and Messrs. Sam E. Whitaker and J. Frank Staley were on the brief of the United States, as amicus curiae, supporting the decision of the state court.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Kolovrat v. Oregon","cite":"366 U.S. 187","y":1961,"id":"1960/102","sc":1,"sum":"An 1881 treaty between the United States and Serbia, which is now a part of Yugoslavia, entitles residents and citizens of Yugoslavia to inherit personal property located in Oregon on the same basis as American next of kin, and these rights have not been taken away or impaired by the monetary policies of Yugoslavia exercised in accordance with later agreements between that country and the United States.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"by":{"0":"28"}},{"t":"case","label":"Morales v. Trans World Airlines, Inc.","cite":"504 U.S. 374","y":1992,"id":"1991/90-1604","sc":1,"op":1,"sum":"The Court held that the Airline Deregulation Act of 1978 prevents states from prohibiting deceptive airline fare advertisements through enforcement of their general consumer protection statuses.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Moran v. New Orleans","cite":"112 U.S. 69","y":1884,"id":"scdb/1884-011","sc":1,"sum":"A municipal ordinance of the city of New Orleans, to establish the rate of-license for professions, callings and other business, which assesses and directs to be collected from persons owning and running towboats to and from the Gulf of Mexico and the city of New Orleans, is a regulation of commerce among the States, and is an infringement of the provisions of Article I., section 8, paragraph 3, of the Constitution …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Ray v. Atlantic Richfield Co.","cite":"435 U.S. 151","y":1978,"id":"1977/76-930","sc":1,"op":8,"sum":"Recognizing Congress anticipated \"arriving at international standards for building tank vessels\" and understanding \"the Nation was to speak with one voice\" on these matters.","sumSrc":"opinion","by":{"0":"passim"}},{"t":"case","label":"Sinnot v. Davenport","cite":"63 U.S. 227","y":1859,"id":"scdb/1859-007","sc":1,"op":2,"sum":"A law of the State of Alabama, passed, in 1854, requiring the owners’ of steamboats navigating the waters of the State, before such boat shall leave the port of Mobile, to file a statement in writing, in the office of the probate judge of Mobile county — setting forth, first, the name of the vessel; second, the name of the owner or owners; third, his or their place or places of residence; fourth, the interest each …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"South Dakota v. Yankton Sioux Tribe","cite":"522 U.S. 329","y":1998,"id":"1997/96-1581","sc":1,"sum":"The Court held that the 1894 statute's operative language and the circumstances surrounding its passage demonstrate that Congress intended to diminish the Yankton Reservation and as a result the unallotted lands ceded did not retain reservation status.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"United States v. Belmont","cite":"301 U.S. 324","y":1937,"id":"1900-1940/301us324","sc":1,"sum":"Justice Sutherland argued for a unanimous Court that different kinds of treaties existed which did not require Senate approval, but nonetheless overrode state statutes. \"Plainly, the external powers of the United States are to be exercised without regard to state laws or policies,\" he reasoned.","sumSrc":"Oyez","by":{"0":"30, 31"}},{"t":"case","label":"United States v. Pink","cite":"315 U.S. 203","y":1942,"id":"1940-1955/315us203","sc":1,"sum":"The Court required New York to release the assets. Justice Douglas affirmed Justice Sutherland's reasoning in Belmont and argued that New York could not \"rewrite our foreign policy to conform to its own domestic policies. Power over external affairs . . . is vested in the national government exclusively.\".","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Weinberger v. Rossi","cite":"456 U.S. 25","y":1982,"id":"1981/80-1924","sc":1,"sum":"The word \"treaty\" as used in § 106 includes executive agreements, such as the one involved here, and is not limited to those international agreements concluded by the President with the advice and consent of the Senate pursuant to Art. II, § 2, cl. 2, of the Constitution.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"White’s Bank v. Smith","cite":"74 U.S. 646","y":1869,"id":"scdb/1868-063","sc":1,"sum":"The case was this:","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Zschernig v. Miller","cite":"389 U.S. 429","y":1968,"id":"1967/21","sc":1,"sum":"As applied by Oregon, each of the three provisions of § 111.070 involves the State in foreign affairs and international relations, matters which the Constitution entrusts solely to the Federal Government. Clark v. Allen, 331 U. S. 503, distinguished. Pp. 432-441. 243 Ore. 567, 592, 412 P. 2d 781, 415 P. 2d 15, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"0":"22, 31"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"0":"35"}},{"t":"law","label":"Pub. L. No. 98-89","url":"https://www.govinfo.gov/link/statute/97/500","by":{"0":"11"}},{"t":"usc","label":"33 U.S.C. § 2701","url":"https://www.law.cornell.edu/uscode/text/33/2701","stext":{"head":"§2701. Definitions","paras":[[0,"For the purposes of this Act, the term—"],[1,"(1) \"act of God\" means an unanticipated grave natural disaster or other natural phenomenon of an exceptional, inevitable, and irresistible character the effects of which could not have been prevented or avoided by the exercise of due care or foresight;"],[1,"(2) \"barrel\" means 42 United States gallons at 60 degrees fahrenheit;"],[1,"(3) \"claim\" means a request, made in writing for a sum certain, for compensation for damages or removal costs resulting from an incident;"],[1,"(4) \"claimant\" means any person or government who presents a claim for compensation under this subchapter;"],[1,"(5) \"damages\" means damages specified in section 2702(b) of this title, and includes the cost of assessing these damages;"],[1,"(6) \"deepwater port\" is a facility licensed under the Deepwater Port Act of 1974 (33 U.S.C. 1501–1524);"],[1,"(7) \"discharge\" means any emission (other than natural seepage), intentional or unintentional, and includes, but is not limited to, spilling, leaking, pumping, pouring, emitting, emptying, or dumping;"],[1,"(8) \"exclusive economic zone\" means the zone established by Presidential Proclamation Numbered 5030, dated March 10, 1983, including the ocean waters of the areas referred to as \"eastern special areas\" in Article 3(1) of the Agreement between the United States of America and the Union of Soviet Socialist Republics on the Maritime Boundary, signed June 1, 1990;"],[1,"(9) \"facility\" means any structure, group of structures, equipment, or device (other than a vessel) which is used for one or more of the following purposes: exploring for, drilling for, producing, storing, handling, transferring, processing, or transporting oil. This term includes any motor vehicle, rolling stock, or pipeline used for one or more of these purposes;"],[1,"(10) \"foreign offshore unit\" means a facility which is located, in whole or in part, in the territorial sea or on the continental shelf of a foreign country and which is or was used for one or more of the following purposes: exploring for, drilling for, producing, storing, handling, transferring, processing, or transporting oil produced from the seabed beneath the foreign country's territorial sea or from the foreign country's continental shelf;"],[1,"(11) \"Fund\" means the Oil Spill Liability Trust Fund, established by section 9509 of title 26;"],[1,"(12) \"gross ton\" has the meaning given that term by the Secretary under part J of title 46;"],[1,"(13) \"guarantor\" means any person, other than the responsible party, who provides evidence of financial responsibility for a responsible party under this Act;"],[1,"(14) \"incident\" means any occurrence or series of occurrences having the same origin, involving one or more vessels, facilities, or any combination thereof, resulting in the discharge or substantial threat of discharge of oil;"],[1,"(15) \"Indian tribe\" means any Indian tribe, band, nation, or other organized group or community, but not including any Alaska Native regional or village corporation, which is recognized as eligible for the special programs and services provided by the United States to Indians because of their status as Indians and has governmental authority over lands belonging to or controlled by the tribe;"],[1,"(16) \"lessee\" means a person holding a leasehold interest in an oil or gas lease on lands beneath navigable waters (as that term is defined in section 1301(a) of title 43) or on submerged lands of the Outer Continental Shelf, granted or maintained under applicable State law or the Outer Continental Shelf Lands Act (43 U.S.C. 1331 et seq.);"],[1,"(17) \"liable\" or \"liability\" shall be construed to be the standard of liability which obtains under section 1321 of this title;"],[1,"(18) \"mobile offshore drilling unit\" means a vessel (other than a self-elevating lift vessel) capable of use as an offshore facility;"],[1,"(19) \"National Contingency Plan\" means the National Contingency Plan prepared and published under section 1321(d) of this title or revised under section 105 of the Comprehensive Environmental Response, Compensation, and Liability Act (42 U.S.C. 9605);"],[1,"(20) \"natural resources\" includes land, fish, wildlife, biota, air, water, ground water, drinking water supplies, and other such resources belonging to, managed by, held in trust by, appertaining to, or otherwise controlled by the United States (including the resources of the exclusive economic zone), any State or local government or Indian tribe, or any foreign government;"],[1,"(21) \"navigable waters\" means the waters of the United States, including the territorial sea;"],[1,"(22) \"offshore facility\" means any facility of any kind located in, on, or under any of the navigable waters of the United States, and any facility of any kind which is subject to the jurisdiction of the United States and is located in, on, or under any other waters, other than a vessel or a public vessel;"],[1,"(23) \"oil\" means oil of any kind or in any form, including petroleum, fuel oil, sludge, oil refuse, and oil mixed with wastes other than dredged spoil, but does not include any substance which is specifically listed or designated as a hazardous substance under subparagraphs (A) through (F) of section 101(14) of the Comprehensive Environmental Response, Compensation, and Liability Act (42 U.S.C. 9601) and which is subject to the provisions of that Act [42 U.S.C. 9601 et seq.];"],[1,"(24) \"onshore facility\" means any facility (including, but not limited to, motor vehicles and rolling stock) of any kind located in, on, or under, any land within the United States other than submerged land;"],[1,"(25) the term \"Outer Continental Shelf facility\" means an offshore facility which is located, in whole or in part, on the Outer Continental Shelf and is or was used for one or more of the following purposes: exploring for, drilling for, producing, storing, handling, transferring, processing, or transporting oil produced from the Outer Continental Shelf;"],[1,"(26) \"owner or operator\"—"],[2,"(A) means—"],[3,"(i) in the case of a vessel, any person owning, operating, or chartering by demise, the vessel;"],[3,"(ii) in the case of an onshore facility, offshore facility, or foreign offshore unit or other facility located seaward of the exclusive economic zone, any person or entity owning or operating such facility;"],[3,"(iii) in the case of any abandoned offshore facility or foreign offshore unit or other facility located seaward of the exclusive economic zone, the person or entity that owned or operated such facility immediately prior to such abandonment;"],[3,"(iv) in the case of any facility, title or control of which was conveyed due to bankruptcy, foreclosure, tax delinquency, abandonment, or similar means to a unit of State or local government, any person who owned, operated, or otherwise controlled activities at such facility immediately beforehand;"],[3,"(v) notwithstanding subparagraph (B)(i), and in the same manner and to the same extent, both procedurally and substantively, as any nongovernmental entity, including for purposes of liability under section 2702 of this title, any State or local government that has caused or contributed to a discharge or substantial threat of a discharge of oil from a vessel or facility ownership or control of which was acquired involuntarily through—"],[4,"(I) seizure or otherwise in connection with law enforcement activity;"],[4,"(II) bankruptcy;"],[4,"(III) tax delinquency;"],[4,"(IV) abandonment; or"],[4,"(V) other circumstances in which the government involuntarily acquires title by virtue of its function as sovereign;"],[3,"(vi) notwithstanding subparagraph (B)(ii), a person that is a lender and that holds indicia of ownership primarily to protect a security interest in a vessel or facility if, while the borrower is still in possession of the vessel or facility encumbered by the security interest, the person—"],[4,"(I) exercises decision making control over the environmental compliance related to the vessel or facility, such that the person has undertaken responsibility for oil handling or disposal practices related to the vessel or facility; or"],[4,"(II) exercises control at a level comparable to that of a manager of the vessel or facility, such that the person has assumed or manifested responsibility—"],[5,"(aa) for the overall management of the vessel or facility encompassing day-to-day decision making with respect to environmental compliance; or"],[5,"(bb) over all or substantially all of the operational functions (as distinguished from financial or administrative functions) of the vessel or facility other than the function of environmental compliance; and"],[2,"(B) does not include—"],[3,"(i) A unit of state or local government that acquired ownership or control of a vessel or facility involuntarily through—"],[4,"(I) seizure or otherwise in connection with law enforcement activity;"],[4,"(II) bankruptcy;"],[4,"(III) tax delinquency;"],[4,"(IV) abandonment; or"],[4,"(V) other circumstances in which the government involuntarily acquires title by virtue of its function as sovereign;"],[3,"(ii) a person that is a lender that does not participate in management of a vessel or facility, but holds indicia of ownership primarily to protect the security interest of the person in the vessel or facility; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/2701?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2701. Definitions","tname":"Navigation and Navigable Waters","by":{"0":"13, 14, 16, 44, 45"}},{"t":"usc","label":"33 U.S.C. § 2718","url":"https://www.law.cornell.edu/uscode/text/33/2718","subs":["(a)","(c)"],"stext":{"head":"§2718. Relationship to other law","paras":[[0,"(a) Preservation of State authorities; Solid Waste Disposal Act"],[0,"Nothing in this Act or the Act of March 3, 1851 shall—"],[1,"(1) affect, or be construed or interpreted as preempting, the authority of any State or political subdivision thereof from imposing any additional liability or requirements with respect to—"],[2,"(A) the discharge of oil or other pollution by oil within such State; or"],[2,"(B) any removal activities in connection with such a discharge; or"],[1,"(2) affect, or be construed or interpreted to affect or modify in any way the obligations or liabilities of any person under the Solid Waste Disposal Act (42 U.S.C. 6901 et seq.) or State law, including common law."],[0,"(b) Preservation of State funds"],[0,"Nothing in this Act or in section 9509 of title 26 shall in any way affect, or be construed to affect, the authority of any State—"],[1,"(1) to establish, or to continue in effect, a fund any purpose of which is to pay for costs or damages arising out of, or directly resulting from, oil pollution or the substantial threat of oil pollution; or"],[1,"(2) to require any person to contribute to such a fund."],[0,"(c) Additional requirements and liabilities; penalties"],[0,"Nothing in this Act, the Act of March 3, 1851 (46 U.S.C. 183 et seq.),1 or section 9509 of title 26, shall in any way affect, or be construed to affect, the authority of the United States or any State or political subdivision thereof—"],[1,"(1) to impose additional liability or additional requirements; or"],[1,"(2) to impose, or to determine the amount of, any fine or penalty (whether criminal or civil in nature) for any violation of law;"],[0,"relating to the discharge, or substantial threat of a discharge, of oil."],[0,"(d) Federal employee liability"],[0,"For purposes of section 2679(b)(2)(B) of title 28, nothing in this Act shall be construed to authorize or create a cause of action against a Federal officer or employee in the officer's or employee's personal or individual capacity for any act or omission while acting within the scope of the officer's or employee's office or employment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/2718?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§2718. Relationship to other law","tname":"Navigation and Navigable Waters","by":{"0":"13, 14, 16, 44, 45, 12, 12"}},{"t":"law","label":"Pub. L. No. 95-474","url":"https://www.govinfo.gov/link/statute/92/1471","by":{"0":"15, 32, 44"}},{"t":"usc","label":"33 U.S.C. § 1221","url":"https://www.law.cornell.edu/uscode/text/33/1221","by":{"0":"10, 24, 25, 26, 27, 28, 39, 10, 24, 25, 26, 27, 28, 39"}},{"t":"usc","label":"33 U.S.C. § 1222","url":"https://www.law.cornell.edu/uscode/text/33/1222","subs":["(b)"],"by":{"0":"27"}},{"t":"usc","label":"33 U.S.C. § 1223","url":"https://www.law.cornell.edu/uscode/text/33/1223","subs":["(a)(1)","(a)(5)"],"stext":{"head":"§1223. Vessel operating requirements","paras":[[0,"(a) In general"],[0,"Subject to the requirements of section 1224 of this title, the Secretary—"],[1,"(1) in any port or place under the jurisdiction of the United States, in the navigable waters of the United States, or in any area covered by an international agreement negotiated pursuant to section 1230 of this title, may construct, operate, maintain, improve, or expand vessel traffic services, consisting of measures for controlling or supervising vessel traffic or for protecting navigation and the marine environment and may include, but need not be limited to one or more of the following: reporting and operating requirements, surveillance and communications systems, routing systems, and fairways;"],[1,"(2) shall require appropriate vessels which operate in an area of a vessel traffic service to utilize or comply with that service;"],[1,"(3) may require vessels to install and use specified navigation equipment, communications equipment, electronic relative motion analyzer equipment, or any electronic or other device necessary to comply with a vessel traffic service or which is necessary in the interests of vessel safety: Provided, That the Secretary shall not require fishing vessels under 300 gross tons as measured under section 14502 of title 46, or an alternate tonnage measured under section 14302 of that title as prescribed by the Secretary under section 14104 of that title or recreational vessels 65 feet or less to possess or use the equipment or devices required by this subsection solely under the authority of this chapter;"],[1,"(4) may control vessel traffic in areas subject to the jurisdiction of the United States which the Secretary determines to be hazardous, or under conditions of reduced visibility, adverse weather, vessel congestion, or other hazardous circumstances by—"],[2,"(A) specifying times of entry, movement, or departure;"],[2,"(B) establishing vessel traffic routing schemes;"],[2,"(C) establishing vessel size, speed, draft limitations and vessel operating conditions; and"],[2,"(D) restricting operation, in any hazardous area or under hazardous conditions, to vessels which have particular operating characteristics or capabilities which he considers necessary for safe operation under the circumstances;"],[1,"(5) may require the receipt of prearrival messages from any vessel, destined for a port or place subject to the jurisdiction of the United States, in sufficient time to permit advance vessel traffic planning prior to port entry, which shall include any information which is not already a matter of record and which the Secretary determines necessary for the control of the vessel and the safety of the port or the marine environment; and"],[1,"(6) may prohibit the use on vessels of electronic or other devices that interfere with communication and navigation equipment, except that such authority shall not apply to electronic or other devices certified to transmit in the maritime services by the Federal Communications Commission and used within the frequency bands 157.1875–157.4375 MHz and 161.7875–162.0375 MHz."],[0,"(b) Special powers"],[0,"The Secretary may order any vessel, in a port or place subject to the jurisdiction of the United States or in the navigable waters of the United States, to operate or anchor in a manner he directs if—"],[1,"(1) he has reasonable cause to believe such vessel does not comply with any regulation issued under this chapter or any other applicable law or treaty;"],[1,"(2) he determines that such vessel does not satisfy the conditions for port entry set forth in section 1228 or 1232c of this title; or"],[1,"(3) by reason of weather, visibility, sea conditions, port congestion, other hazardous circumstances, or the condition of such vessel, he is satisfied that such directive is justified in the interest of safety."],[0,"(c) Port access routes"],[0,"(1) In order to provide safe access routes for the movement of vessel traffic proceeding to or from ports or places subject to the jurisdiction of the United States, and subject to the requirements of paragraph (3) hereof, the Secretary shall designate necessary fairways and traffic separation schemes for vessels operating in the territorial sea of the United States and in high seas approaches, outside the territorial sea, to such ports or places. Such a designation shall recognize, within the designated area, the paramount right of navigation over all other uses."],[0,"(2) No designation may be made by the Secretary pursuant to this subsection, if such a designation, as implemented, would deprive any person of the effective exercise of a right granted by a lease or permit executed or issued under other applicable provisions of law: Provided, That such right has become vested prior to the time of publication of the notice required by clause (A) of paragraph (3) hereof: Provided further, That the determination as to whether the designation would so deprive any such person shall be made by the Secretary, after consultation with the responsible official under whose authority the lease was executed or the permit issued."],[0,"(3) Prior to making a designation pursuant to paragraph (1) hereof, and in accordance with the requirements of section 1224 of this title, the Secretary shall—"],[1,"(A) within six months after date of enactment of this Act (and may, from time to time thereafter), undertake a study of the potential traffic density and the need for safe access routes for vessels in any area for which fairways or traffic separation schemes are proposed or which may otherwise be considered and shall publish notice of such undertaking in the Federal Register;"],[1,"(B) in consultation with the Secretary of State, the Secretary of the Interior, the Secretary of Commerce, the Secretary of the Army, and the Governors of affected States, as their responsibilities may require, take into account all other uses of the area under consideration (including, as appropriate, the exploration for, or exploitation of, oil, gas, or other mineral resources, the construction or operation of deepwater ports or other structures on or above the seabed or subsoil of the submerged lands or the Outer Continental Shelf of the United States, the establishment or operation of marine or estuarine sanctuaries, and activities involving recreational or commercial fishing); and"],[1,"(C) to the extent practicable, reconcile the need for safe access routes with the needs of all other reasonable uses of the area involved."],[0,"(4) In carrying out his responsibilities under paragraph (3), the Secretary shall proceed expeditiously to complete any study undertaken. Thereafter, he shall promptly issue a notice of proposed rule-making for the designation contemplated or shall have published in the Federal Register a notice that no designation is contemplated as a result of the study and the reason for such determination."],[0,"(5) In connection with a designation made pursuant to this subsection, the Secretary—"],[1,"(A) shall issue reasonable rules and regulations governing the use of such designated areas, including the applicability of rules 9 and 10 of the International Regulations for Preventing Collisions at Sea, 1972, relating to narrow channels and traffic separation schemes, respectively, in waters where such regulations apply;"],[1,"(B) to the extent that he finds reasonable and necessary to effectuate the purposes of the designation, make the use of designated fairways and traffic separation schemes mandatory for specific types and sizes of vessels, foreign and domestic, operating in the territorial sea of the United States and for specific types and sizes of vessels of the United States operating on the high seas beyond the territorial sea of the United States;"],[1,"(C) may, from time to time, as necessary, adjust the location or limits of designated fairways or traffic separation schemes, in order to accommodate the needs of other uses which cannot be reasonably accommodated otherwise: Provided, That such an adjustment will not, in the judgement of the Secretary, unacceptably adversely affect the purpose for which the existing designation was made and the need for which continues; and"],[1,"(D) shall, through appropriate channels, (i) notify cognizant international organizations of any designation, or adjustment thereof, and (ii) take action to seek the cooperation of foreign States in making it mandatory for vessels under their control to use any fairway or traffic separation scheme designated pursuant to this subsection in any area of the high seas, to the same extent as required by the Secretary for vessels of the United States."],[0,"(d) Exception"],[0,"Except pursuant to international treaty, convention, or agreement, to which the United States is a party, this chapter shall not apply to any foreign vessel that is not destined for, or departing from, a port or place subject to the jurisdiction of the United States and that is in—"],[1,"(1) innocent passage through the territorial sea of the United States, or"],[1,"(2) transit through the navigable waters of the United States which form a part of an international strait."],[0,"(e) Cooperative agreements"],[0,"(1) The Secretary may enter into cooperative agreements with public or private agencies, authorities, associations, institutions, corporations, organizations, or other persons to carry out the functions under subsection (a)(1)."]],"more":true,"ed":"2017","src":"https://www.govinfo.gov/link/uscode/33/1223?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1223. Vessel operating requirements","tname":"Navigation and Navigable Waters","by":{"0":"6, 26, 37, 33, 39"}},{"t":"usc","label":"33 U.S.C. § 1224","url":"https://www.law.cornell.edu/uscode/text/33/1224","subs":["(a)"],"by":{"0":"26, 33"}},{"t":"usc","label":"33 U.S.C. § 1228","url":"https://www.law.cornell.edu/uscode/text/33/1228","subs":["(a)(2)"],"stext":{"head":"§1228. Conditions for entry to ports in the United States","paras":[[0,"(a) In general"],[0,"No vessel, subject to the provisions of chapter 37 of title 46, shall operate in the navigable waters of the United States or transfer cargo or residue in any port or place under the jurisdiction of the United States, if such vessel—"],[1,"(1) has a history of accidents, pollution incidents, or serious repair problems which, as determined by the Secretary, creates reason to believe that such vessel may be unsafe or may create a threat to the marine environment; or"],[1,"(2) fails to comply with any applicable regulation issued under this chapter, chapter 37 of title 46, or under any other applicable law or treaty; or"],[1,"(3) discharges oil or hazardous material in violation of any law of the United States or in a manner or quantities inconsistent with the provisions of any treaty to which the United States is a party; or"],[1,"(4) does not comply with any applicable vessel traffic service requirements; or"],[1,"(5) is manned by one or more officers who are licensed by a certificating state which the Secretary has determined, pursuant to section 9101 of title 46, does not have standards for licensing and certification of seafarers which are comparable to or more stringent than United States standards or international standards which are accepted by the United States; or"],[1,"(6) is not manned in compliance with manning levels as determined by the Secretary to be necessary to insure the safe navigation of the vessel; or"],[1,"(7) while underway, does not have at least one licensed deck officer on the navigation bridge who is capable of clearly understanding English."],[0,"(b) Exceptions"],[0,"The Secretary may allow provisional entry of a vessel not in compliance with subsection (a), if the owner or operator of such vessel proves, to the satisfaction of the Secretary, that such vessel is not unsafe or a threat to the marine environment, and if such entry is necessary for the safety of the vessel or persons aboard. In addition, paragraphs (1), (2), (3), and (4) of subsection (a) shall not apply if the owner or operator of such vessel proves, to the satisfaction of the Secretary, that such vessel is no longer unsafe or a threat to the marine environment, and is no longer in violation of any applicable law, treaty, regulation or condition, as appropriate. Clauses (5) and (6) of subsection (a) shall become applicable eighteen months after October 17, 1978."]],"more":false,"ed":"2017","src":"https://www.govinfo.gov/link/uscode/33/1228?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1228. Conditions for entry to ports in the United States","tname":"Navigation and Navigable Waters","by":{"0":"33"}},{"t":"usc","label":"33 U.S.C. § 1230","url":"https://www.law.cornell.edu/uscode/text/33/1230","subs":["(b)(1)"],"by":{"0":"49, 48"}},{"t":"usc","label":"33 U.S.C. § 1231","url":"https://www.law.cornell.edu/uscode/text/33/1231","subs":["(b)"],"by":{"0":"42, 45, 33"}},{"t":"usc","label":"33 U.S.C. § 1232","url":"https://www.law.cornell.edu/uscode/text/33/1232","by":{"0":"33"}},{"t":"usc","label":"33 U.S.C. § 1901","url":"https://www.law.cornell.edu/uscode/text/33/1901","by":{"0":"33"}},{"t":"usc","label":"46 U.S.C. § 2101","url":"https://www.law.cornell.edu/uscode/text/46/2101","by":{"0":"3, 24, 25, 26, 28, 32"}},{"t":"usc","label":"46 U.S.C. § 391a","url":"https://www.law.cornell.edu/uscode/text/46/391a","subs":["(2)","(5)"],"op":1,"tname":"Shipping","by":{"0":"10, 24, 23, 30"}},{"t":"usc","label":"46 U.S.C. § 3101","url":"https://www.law.cornell.edu/uscode/text/46/3101","by":{"0":"46"}},{"t":"usc","label":"46 U.S.C. § 3201","url":"https://www.law.cornell.edu/uscode/text/46/3201","by":{"0":"46"}},{"t":"usc","label":"46 U.S.C. § 3203","url":"https://www.law.cornell.edu/uscode/text/46/3203","subs":["(a)","(b)"],"by":{"0":"37, 31, 37"}},{"t":"usc","label":"46 U.S.C. § 3205","url":"https://www.law.cornell.edu/uscode/text/46/3205","by":{"0":"46"}},{"t":"usc","label":"46 U.S.C. § 3701","url":"https://www.law.cornell.edu/uscode/text/46/3701","by":{"0":"10"}},{"t":"usc","label":"46 U.S.C. § 3702","url":"https://www.law.cornell.edu/uscode/text/46/3702","subs":["(a)"],"by":{"0":"43"}},{"t":"usc","label":"46 U.S.C. § 3703","url":"https://www.law.cornell.edu/uscode/text/46/3703","subs":["(a)","(a)(1)"],"stext":{"head":"§3703. Regulations","paras":[[0,"(a) The Secretary shall prescribe regulations for the design, construction, alteration, repair, maintenance, operation, equipping, personnel qualification, and manning of vessels to which this chapter applies, that may be necessary for increased protection against hazards to life and property, for navigation and vessel safety, and for enhanced protection of the marine environment. The Secretary may prescribe different regulations applicable to vessels engaged in the domestic trade, and also may prescribe regulations that exceed standards set internationally. Regulations prescribed by the Secretary under this subsection are in addition to regulations prescribed under other laws that may apply to any of those vessels. Regulations prescribed under this subsection shall include requirements about—"],[1,"(1) superstructures, hulls, cargo holds or tanks, fittings, equipment, appliances, propulsion machinery, auxiliary machinery, and boilers;"],[1,"(2) the handling or stowage of cargo, the manner of handling or stowage of cargo, and the machinery and appliances used in the handling or stowage;"],[1,"(3) equipment and appliances for lifesaving, fire protection, and prevention and mitigation of damage to the marine environment;"],[1,"(4) the manning of vessels and the duties, qualifications, and training of the officers and crew;"],[1,"(5) improvements in vessel maneuvering and stopping ability and other features that reduce the possibility of marine casualties;"],[1,"(6) the reduction of cargo loss if a marine casualty occurs; and"],[1,"(7) the reduction or elimination of discharges during ballasting, deballasting, tank cleaning, cargo handling, or other such activity."],[0,"(b) In prescribing regulations under subsection (a) of this section, the Secretary shall consider the types and grades of cargo permitted to be on board a tank vessel."],[0,"(c) In prescribing regulations under subsection (a) of this section, the Secretary shall establish procedures for consulting with, and receiving and considering the views of—"],[1,"(1) interested departments, agencies, and instrumentalities of the United States Government;"],[1,"(2) officials of State and local governments;"],[1,"(3) representatives of port and harbor authorities and associations;"],[1,"(4) representatives of environmental groups; and"],[1,"(5) other interested parties knowledgeable or experienced in dealing with problems involving vessel safety, port and waterways safety, and protection of the marine environment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/46/3703?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§3703. Regulations","tname":"Shipping","by":{"0":"7, 38, 40, 42, 45, 6, 24, 26, 32, 35, 36, 37, 40, 43, 46"}},{"t":"usc","label":"46 U.S.C. § 3703a","url":"https://www.law.cornell.edu/uscode/text/46/3703a","subs":["(a)"],"stext":{"head":"§3703a. Tank vessel construction standards","paras":[[0,"(a) Except as otherwise provided in this section, a vessel to which this chapter applies shall be equipped with a double hull—"],[1,"(1) if it is constructed or adapted to carry, or carries, oil in bulk as cargo or cargo residue; and"],[1,"(2) when operating on the waters subject to the jurisdiction of the United States, including the Exclusive Economic Zone."],[0,"(b) This section does not apply to—"],[1,"(1) a vessel used only to respond to a discharge of oil or a hazardous substance;"],[1,"(2) a vessel of less than 5,000 gross tons as measured under section 14502 of this title, or an alternate tonnage measured under section 14302 of this title as prescribed by the Secretary under section 14104 of this title equipped with a double containment system determined by the Secretary to be as effective as a double hull for the prevention of a discharge of oil;"],[1,"(3) a vessel documented under chapter 121 of this title that was equipped with a double hull before August 12, 1992;"],[1,"(4) a barge of less than 1,500 gross tons (as measured under chapter 145 of this title) carrying refined petroleum product in bulk as cargo in or adjacent to waters of the Bering Sea, Chukchi Sea, and Arctic Ocean and waters tributary thereto and in the waters of the Aleutian Islands and the Alaskan Peninsula west of 155 degrees west longitude; or"],[1,"(5) a vessel in the National Defense Reserve Fleet pursuant to section 57100."],[0,"(c)(1) In this subsection, the age of a vessel is determined from the later of the date on which the vessel—"],[1,"(A) is delivered after original construction;"],[1,"(B) is delivered after completion of a major conversion; or"],[1,"(C) had its appraised salvage value determined by the Coast Guard and is qualified for documentation as a wrecked vessel under section 12112 of this title."],[0,"(2) A vessel of less than 5,000 gross tons as measured under section 14502 of this title, or an alternate tonnage measured under section 14302 of this title as prescribed by the Secretary under section 14104 of this title for which a building contract or contract for major conversion was placed before June 30, 1990, and that was delivered under that contract before January 1, 1994, and a vessel of less than 5,000 gross tons as measured under section 14502 of this title, or an alternate tonnage measured under section 14302 of this title as prescribed by the Secretary under section 14104 of this title that had its appraised salvage value determined by the Coast Guard before June 30, 1990, and that qualified for documentation as a wrecked vessel under section 12112 of this title before January 1, 1994, may not operate in the navigable waters or the Exclusive Economic Zone of the United States unless the vessel is equipped with a double hull or with a double containment system determined by the Secretary to be as effective as a double hull for the prevention of a discharge of oil."],[0,"(3) A vessel for which a building contract or contract for major conversion was placed before June 30, 1990, and that was delivered under that contract before January 1, 1994, and a vessel that had its appraised salvage value determined by the Coast Guard before June 30, 1990, and that qualified for documentation as a wrecked vessel under section 12112 of this title before January 1, 1994, may not operate in the navigable waters or Exclusive Economic Zone of the United States unless equipped with a double hull—"],[1,"(A) in the case of a vessel of at least 5,000 gross tons but less than 15,000 gross tons as measured under section 14502, or an alternate tonnage measured under section 14302 as prescribed by the Secretary under section 14104, if the vessel is 25 years old or older and has a single hull, or is 30 years old or older and has a double bottom or double sides;"],[1,"(B) in the case of a vessel of at least 15,000 gross tons but less than 30,000 gross tons as measured under section 14502, or an alternate tonnage measured under section 14302 as prescribed by the Secretary under section 14104, if the vessel is 25 years old or older and has a single hull, or is 30 years old or older and has a double bottom or double sides; and"],[1,"(C) in the case of a vessel of at least 30,000 gross tons as measured under section 14502, or an alternate tonnage measured under section 14302 as prescribed by the Secretary under section 14104, if the vessel is 23 years old or older and has a single hull, or is 28 years old or older and has a double bottom or double sides."],[0,"(4) Except as provided in subsection (b) of this section—"],[1,"(A) a vessel that has a single hull may not operate after January 1, 2010; and"],[1,"(B) a vessel that has a double bottom or double sides may not operate after January 1, 2015."],[0,"(d) The operation of barges described in subsection (b)(5) outside waters described in that subsection shall be on any conditions as the Secretary may require."],[0,"(e)(1) For the purposes of this section, the gross tonnage of a vessel shall be the gross tonnage that would have been recognized by the Secretary on July 1, 1997, as the tonnage measured under section 14502 of this title, or as an alternate tonnage measured under section 14302 of this title as prescribed by the Secretary under section 14104 of this title."],[0,"(2) This subsection does not apply to a tank vessel that, before July 1, 1997, had undergone, or was the subject of a contract for, alterations that reduce the gross tonnage of the tank vessel, as shown by reliable evidence acceptable to the Secretary."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/46/3703a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3703a. Tank vessel construction standards","tname":"Shipping","by":{"0":"43, 45"}},{"t":"usc","label":"46 U.S.C. § 3710","url":"https://www.law.cornell.edu/uscode/text/46/3710","subs":["(a)"],"by":{"0":"46"}},{"t":"usc","label":"46 U.S.C. § 3711","url":"https://www.law.cornell.edu/uscode/text/46/3711","subs":["(a)"],"by":{"0":"6, 30"}},{"t":"usc","label":"46 U.S.C. § 3717","url":"https://www.law.cornell.edu/uscode/text/46/3717","subs":["(a)(4)"],"by":{"0":"39"}},{"t":"usc","label":"46 U.S.C. § 6101","url":"https://www.law.cornell.edu/uscode/text/46/6101","stext":{"head":"§6101. Marine casualties and reporting","paras":[[0,"(a) The Secretary shall prescribe regulations on the marine casualties to be reported and the manner of reporting. The regulations shall require reporting the following marine casualties:"],[1,"(1) death of an individual."],[1,"(2) serious injury to an individual."],[1,"(3) material loss of property."],[1,"(4) material damage affecting the seaworthiness or efficiency of the vessel."],[1,"(5) significant harm to the environment."],[0,"(b) A marine casualty shall be reported within 5 days as provided in this part and regulations prescribed under this part. Each report filed under this section shall include information as to whether the use of alcohol contributed to the casualty."],[0,"(c) Notice to State and Tribal Governments.—Not later than 24 hours after receiving a notice of a major marine casualty under this section, the Secretary shall notify each State or federally recognized Indian tribe that is, or may reasonably be expected to be, affected by such marine casualty."],[0,"(d)(1) This part applies to a foreign vessel when involved in a marine casualty on the navigable waters of the United States."],[0,"(2) This part applies, to the extent consistent with generally recognized principles of international law, to a foreign vessel constructed or adapted to carry, or that carries, oil in bulk as cargo or cargo residue involved in a marine casualty described under subsection (a)(4) or (5) in waters subject to the jurisdiction of the United States, including the Exclusive Economic Zone."],[0,"(e) A marine casualty not resulting in the death of an individual shall be classified according to the gravity of the casualty, as prescribed by regulation, giving consideration to the extent of injuries to individuals, the extent of property damage, the dangers that the casualty creates, and the size, occupation, and means of propulsion of each vessel involved."],[0,"(f)(1) This chapter applies to a marine casualty involving a United States citizen on a foreign passenger vessel operating south of 75 degrees north latitude, west of 35 degrees west longitude, and east of the International Date Line; or operating in the area south of 60 degrees south latitude that—"],[1,"(A) embarks or disembarks passengers in the United States; or"],[1,"(B) transports passengers traveling under any form of air and sea ticket package marketed in the United States."],[0,"(2) When there is a marine casualty described in paragraph (1) of this subsection and an investigation is conducted, the Secretary shall ensure that the investigation—"],[1,"(A) is thorough and timely; and"],[1,"(B) produces findings and recommendations to improve safety on passenger vessels."],[0,"(3) When there is a marine casualty described in paragraph (1) of this subsection, the Secretary may—"],[1,"(A) seek a multinational investigation of the casualty under auspices of the International Maritime Organization; or"],[1,"(B) conduct an investigation of the casualty under chapter 63 of this title."],[0,"(g) To the extent consistent with generally recognized practices and procedures of international law, this part applies to a foreign vessel involved in a marine casualty or incident, as defined in the International Maritime Organization Code for the Investigation of Marine Casualties and Incidents, where the United States is a Substantially Interested State and is, or has the consent of, the Lead Investigating State under the Code."],[0,"(h) The Secretary shall publish all major marine casualty reports prepared in accordance with this section in an electronic form, and shall provide information electronically regarding how other marine casualty reports can be obtained."],[0,"(i) For purposes of this section, the term \"major marine casualty\" means a casualty involving a vessel, other than a public vessel, that results in—"],[1,"(1) the loss of 6 or more lives;"],[1,"(2) the loss of a mechanically propelled vessel of 100 or more gross tons;"],[1,"(3) property damage initially estimated at $2,000,000 or more; or"],[1,"(4) serious threat, as determined by the Commandant with concurrence by the Chairman of the National Transportation Safety Board, to life, property, or the environment by hazardous materials."],[0,"(j) The Secretary shall publish all marine casualty reports prepared in accordance with this section in an electronic form."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/46/6101?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§6101. Marine casualties and reporting","tname":"Shipping","by":{"0":"46"}},{"t":"usc","label":"46 U.S.C. § 6301","url":"https://www.law.cornell.edu/uscode/text/46/6301","by":{"0":"39"}},{"t":"usc","label":"46 U.S.C. § 7101","url":"https://www.law.cornell.edu/uscode/text/46/7101","by":{"0":"46"}},{"t":"usc","label":"46 U.S.C. § 8104","url":"https://www.law.cornell.edu/uscode/text/46/8104","subs":["(n)"],"by":{"0":"38"}},{"t":"usc","label":"46 U.S.C. § 8304","url":"https://www.law.cornell.edu/uscode/text/46/8304","by":{"0":"46"}},{"t":"usc","label":"46 U.S.C. § 8502","url":"https://www.law.cornell.edu/uscode/text/46/8502","subs":["(h)"],"by":{"0":"37"}},{"t":"usc","label":"46 U.S.C. § 8503","url":"https://www.law.cornell.edu/uscode/text/46/8503","by":{"0":"22"}},{"t":"usc","label":"46 U.S.C. § 8702","url":"https://www.law.cornell.edu/uscode/text/46/8702","subs":["(b)"],"by":{"0":"36"}},{"t":"usc","label":"46 U.S.C. § 9101","url":"https://www.law.cornell.edu/uscode/text/46/9101","subs":["(a)"],"by":{"0":"38, 36, 32, 42"}},{"t":"usc","label":"46 U.S.C. § 9102","url":"https://www.law.cornell.edu/uscode/text/46/9102","subs":["(a)(5)"],"by":{"0":"36, 5, 15, 23, 44"}},{"t":"reg","label":"3 C.F.R. pt. 277","url":"https://www.ecfr.gov/current/title-3/part-277","by":{"0":"3, 8, 31"}},{"t":"reg","label":"57 Fed. Reg. 31,274","url":"https://www.govinfo.gov/link/fr/57/31274","by":{"0":"34"}},{"t":"reg","label":"58 Fed. Reg. 27,632","url":"https://www.govinfo.gov/link/fr/58/27632","by":{"0":"37, 46"}},{"t":"reg","label":"59 Fed. Reg. 65,500","url":"https://www.govinfo.gov/link/fr/59/65500","by":{"0":"34"}},{"t":"reg","label":"60 Fed. Reg. 24,767","url":"https://www.govinfo.gov/link/fr/60/24767","by":{"0":"61"}},{"t":"reg","label":"63 Fed. Reg. 71,770","url":"https://www.govinfo.gov/link/fr/63/71770","by":{"0":"46"}}]};